        aapl_close = data.Bars[self.aapl].Close

        strategy_a_ready = (
            self.spy_sma.IsReady and
            self.previous_spy_sma is not None
        )
        strategy_b_ready = (
            self.aapl_rsi.IsReady and
            self.aapl_close_count >= 4
        )

        # Evaluate sells before buys.
        if self.strategy_a_shares > 0 and strategy_a_ready:
            if spy_close < self.spy_sma.Current.Value and self.previous_spy_sma <= self.previous_spy_sma:
                # The condition above is completed below using the stored prior close.
                pass

        if self.strategy_a_shares > 0 and strategy_a_ready:
            previous_spy_close = self._previous_spy_close
            if previous_spy_close <= self.previous_spy_sma and spy_close < self.spy_sma.Current.Value:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and strategy_b_ready:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and strategy_a_ready:
            previous_spy_close = self._previous_spy_close
            if previous_spy_close <= self.previous_spy_sma and spy_close > self.spy_sma.Current.Value:
                shares = int((0.40 * self.Portfolio.TotalPortfolioValue) // spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and strategy_b_ready:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

        self._store_spy_sma()

    def _store_spy_sma(self):
        if self.spy_sma.IsReady:
            self.previous_spy_sma = float(self.spy_sma.Current.Value)

    @property
    def _previous_spy_close(self):
        return self._spy_close_history[0] if hasattr(self, "_spy_close_history") and self._spy_close_history.Count > 0 else 0
